const clone = value => JSON.parse(JSON.stringify(value));
const uid = (prefix="id") => `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const escapeHTML = value => String(value ?? "").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;");
const normalizeText = value => String(value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
function loadJSON(key,fallback){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):clone(fallback)}catch{return clone(fallback)}}
function saveJSON(key,value){localStorage.setItem(key,JSON.stringify(value))}
function getChecklist(){const v=loadJSON(STORAGE.checklist,DEFAULT_CHECKLIST);if(!localStorage.getItem(STORAGE.checklist))saveJSON(STORAGE.checklist,v);return Array.isArray(v)?v:clone(DEFAULT_CHECKLIST)}
function getContacts(){const v=loadJSON(STORAGE.contacts,[]);return Array.isArray(v)?v:[]}
function getPlan(){return Object.assign({meeting:"",backupMeeting:"",radio:"",checkin:"",backupMethod:"",message:"",notes:""},loadJSON(STORAGE.plan,{}))}
function getFavorites(){const v=loadJSON(STORAGE.favorites,[]);return Array.isArray(v)?v:[]}
function getLastPosition(){return loadJSON(STORAGE.lastPosition,null)}
function getICE(){return Object.assign({name:"",birthDate:"",iceName:"",icePhone:"",bloodType:"",allergies:"",medications:"",conditions:"",notes:""},loadJSON(STORAGE.ice,{}))}
function getJournal(){const v=loadJSON(STORAGE.journal,[]);return Array.isArray(v)?v:[]}
function getInventory(){const v=loadJSON(STORAGE.inventory,[]);return Array.isArray(v)?v:[]}
function getMaintenance(){const v=loadJSON(STORAGE.maintenance,[]);return Array.isArray(v)?v:[]}
function getResources(){const v=loadJSON(STORAGE.resources,[]);return Array.isArray(v)?v:[]}
function getSettings(){return Object.assign({textLarge:false},loadJSON(STORAGE.settings,{}))}
function migrateData(){
  getChecklist(); getContacts(); saveJSON(STORAGE.plan,getPlan());
  if(!localStorage.getItem(STORAGE.favorites))saveJSON(STORAGE.favorites,[]);
  if(!localStorage.getItem(STORAGE.ice))saveJSON(STORAGE.ice,getICE());
  for(const key of [STORAGE.journal,STORAGE.inventory,STORAGE.maintenance,STORAGE.resources]) if(!localStorage.getItem(key))saveJSON(key,[]);
  if(!localStorage.getItem(STORAGE.settings))saveJSON(STORAGE.settings,getSettings());
  localStorage.setItem(STORAGE.schema,String(CURRENT_SCHEMA));
}
function applySettings(){document.body.classList.toggle("text-large",!!getSettings().textLarge)}
function showToast(message){clearTimeout(toastTimer);toast.textContent=message;toast.hidden=false;toastTimer=setTimeout(()=>toast.hidden=true,2400)}
function openModal(title,html){modalTitle.textContent=title;modalBody.innerHTML=html;modal.hidden=false;document.body.style.overflow="hidden"}
function closeModal(){modal.hidden=true;modalBody.innerHTML="";document.body.style.overflow=""}
function pageHeader(icon,title,description){return `<header class="page-header"><h1>${icon} ${title}</h1><p>${description}</p></header>`}
function emergencyCalls(numbers=["190","192","193","199"]){const names={190:"Polícia",192:"SAMU",193:"Bombeiros",199:"Defesa Civil"};return `<div class="emergency-calls">${numbers.map(n=>`<a class="call-button" href="tel:${n}">📞 ${n} · ${names[n]||"Ligar"}</a>`).join("")}</div>`}
function bigEmergencyCalls(){return `<div class="emergency-call-grid">${[["190","Polícia"],["192","SAMU"],["193","Bombeiros"],["199","Defesa Civil"]].map(x=>`<a class="big-call" href="tel:${x[0]}"><strong>${x[0]}</strong><span>${x[1]}</span></a>`).join("")}</div>`}
function resourceCard(target,icon,title,description){return `<div class="resource-card"><button class="action-card" data-nav="${target}"><span class="emoji">${icon}</span><span><strong>${title}</strong><small>${description}</small></span></button>${favoriteButton("view",target)}</div>`}
function favoriteToken(type,id){return `${type}:${id}`}
function isFavorite(type,id){return getFavorites().includes(favoriteToken(type,id))}
function favoriteButton(type,id){const active=isFavorite(type,id);return `<button class="fav-button ${active?"active":""}" data-fav-type="${type}" data-fav-id="${id}" aria-label="${active?"Remover dos favoritos":"Adicionar aos favoritos"}">${active?"★":"☆"}</button>`}
function toggleFavorite(type,id){let list=getFavorites(),token=favoriteToken(type,id);if(list.includes(token))list=list.filter(x=>x!==token);else list.push(token);saveJSON(STORAGE.favorites,list);showToast(list.includes(token)?"Adicionado aos favoritos":"Removido dos favoritos")}
function favoriteInfo(token){const [type,id]=token.split(":");if(type==="emergency"){const e=EMERGENCIES.find(x=>x.id===id);return e?{type,id,icon:e.icon,title:e.title,description:e.summary}:null}const m=MODULES.find(x=>x[0]===id);return m?{type:"view",id,icon:m[1],title:m[2],description:m[3]}:null}
function favoritesHTML(){const items=getFavorites().map(favoriteInfo).filter(Boolean).slice(0,8);if(!items.length)return "";return `<div class="section-title"><h2>⭐ Favoritos</h2><span>${items.length}</span></div><div class="favorite-grid">${items.map(i=>`<div class="favorite-card"><button class="favorite-open" data-favorite-open="${i.type}" data-favorite-id="${i.id}"><span>${i.icon}</span><strong>${i.title}</strong><small>${i.description}</small></button><button class="favorite-remove" data-fav-type="${i.type}" data-fav-id="${i.id}">★</button></div>`).join("")}</div>`}

function formatWhen(iso){if(!iso)return "";try{return new Intl.DateTimeFormat("pt-BR",{dateStyle:"short",timeStyle:"short"}).format(new Date(iso))}catch{return iso}}
function formatDate(date){if(!date)return "";const [y,m,d]=date.split("-");return `${d}/${m}/${y}`}
function localDateValue(){const d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),day=String(d.getDate()).padStart(2,"0");return `${y}-${m}-${day}`}
function daysFromToday(date){if(!date)return null;const today=new Date();today.setHours(12,0,0,0);const target=new Date(date+"T12:00:00");return Math.ceil((target-today)/86400000)}
function inventoryStatus(item){const low=Number(item.minimum)>0&&Number(item.quantity)<=Number(item.minimum);const dd=daysFromToday(item.expiry);const expired=dd!==null&&dd<0;const expiring=dd!==null&&dd>=0&&dd<=30;return {low,expired,expiring,dd}}
function maintenanceStatus(item){const dd=daysFromToday(item.due);return {due:dd!==null&&dd<=0,soon:dd!==null&&dd>0&&dd<=14,dd}}
function getAttentionCount(){return getInventory().filter(i=>{const s=inventoryStatus(i);return s.low||s.expired||s.expiring}).length+getMaintenance().filter(i=>{const s=maintenanceStatus(i);return s.due||s.soon}).length}
function lastPositionHTML(compact=false){const p=getLastPosition();if(!p)return `<div class="last-location"><small>Nenhuma posição salva ainda.</small></div>`;const text=`${Number(p.lat).toFixed(6)}, ${Number(p.lon).toFixed(6)}`;return `<div class="last-location"><strong>${text}</strong><small>±${Math.round(Number(p.accuracy)||0)} m · ${formatWhen(p.timestamp)}</small>${compact?"":`<div class="btn-row"><button class="btn" data-copy="${text}">Copiar</button><button class="btn" data-nav="navegacao">Atualizar GPS</button></div>`}</div>`}

function renderHome(){const attention=getAttentionCount();view.innerHTML=`
  <div class="emergency-now"><div class="emergency-now-head"><span>EMERGÊNCIA BRASIL</span><small>1 toque</small></div>${bigEmergencyCalls()}</div>
  <button class="home-main-sos" data-nav="modo-emergencia"><span>🆘</span> MODO EMERGÊNCIA</button>
  <button class="home-position" data-nav="navegacao"><div><b>📍 MINHA POSIÇÃO</b><small>${getLastPosition()?"Última posição salva disponível":"Toque para obter coordenadas"}</small></div><span>›</span></button>
  ${attention?`<button class="alert-strip" data-nav="estoque"><span><strong>⚠️ ${attention} aviso(s)</strong><br><small>Estoque, validade ou manutenção</small></span><b>›</b></button>`:""}
  <div class="section-title"><h2>Acesso rápido</h2><span>offline</span></div>
  <div class="home-core">${resourceCard("agua","💧","Água","Reserva e tratamento")}${resourceCard("checklist","🎒","Checklist","Kit e preparo")}${resourceCard("energia","🔋","Energia","Bateria e power bank")}${resourceCard("navegacao","🧭","Navegação","GPS e orientação")}</div>
  ${favoritesHTML()}
  <button class="wide-more" data-nav="mais"><span>☰</span><div><strong>Todos os recursos</strong><small>ICE, diário, estoque, abrigo, comunicação, calculadoras e mais</small></div><b>›</b></button>`}

const CRITICAL_IDS=["inconsciente","hemorragia","incendio","enchente","transito","perdido"];
function renderEmergencyMode(){const critical=CRITICAL_IDS.map(id=>EMERGENCIES.find(e=>e.id===id)).filter(Boolean);view.innerHTML=`${pageHeader("🆘","Modo Emergência","Somente ações críticas para reduzir tempo de procura.")}<div class="emergency-now">${bigEmergencyCalls()}</div><section class="panel priority-panel"><h2>📍 Localização</h2>${lastPositionHTML()}<button class="btn primary full" data-gps="emergency">Atualizar posição agora</button><div id="emergencyGpsResult" class="result" hidden></div></section><div class="critical-action-grid">${critical.map(e=>`<button class="critical-action" data-emergency="${e.id}"><span>${e.icon}</span><strong>${e.title}</strong><small>${e.summary}</small></button>`).join("")}</div><button class="wide-more" data-nav="emergencias"><span>🔎</span><div><strong>Todas as emergências</strong><small>Buscar outros protocolos</small></div><b>›</b></button>`}
function renderEmergencyList(items){return items.map(e=>`<article class="list-card clickable emergency-row" data-emergency="${e.id}"><h3>${e.icon} ${e.title}</h3><p>${e.summary}</p>${favoriteButton("emergency",e.id)}</article>`).join("")}
function renderEmergencies(){view.innerHTML=`${pageHeader("🆘","Emergências","Busque pelo problema ou por palavras como sangue, cobra, sem sinal ou calor.")}<div class="search-wrapper"><span>⌕</span><input id="emergencySearch" class="search" type="search" placeholder="Buscar emergência..."></div><section class="panel"><strong>PARE → OBSERVE → PENSE → AJA</strong>${emergencyCalls()}</section><div id="emergencyList" class="list">${renderEmergencyList(EMERGENCIES)}</div>`}
function showEmergency(id){const e=EMERGENCIES.find(x=>x.id===id);if(!e)return;openModal(`${e.icon} ${e.title}`,`<div style="position:relative">${favoriteButton("emergency",e.id)}<div class="notice danger"><strong>Primeiro:</strong> não se coloque em risco para ajudar outra pessoa.</div><h3>O que fazer</h3><ol class="protocol">${e.steps.map(s=>`<li>${s}</li>`).join("")}</ol>${e.dont?.length?`<h3>Evite</h3><ul class="dont">${e.dont.map(s=>`<li>${s}</li>`).join("")}</ul>`:""}${e.calls?emergencyCalls(e.calls):""}<div class="notice warning">Guia resumido. Quando houver atendimento disponível, siga a orientação profissional.</div></div>`)}

function waterCalculator(prefix){return `<form id="${prefix}WaterForm"><div class="form-grid"><div class="field"><label>Pessoas</label><input name="people" type="number" min="1" value="1" required></div><div class="field"><label>Dias</label><input name="days" type="number" min="1" value="3" required></div><div class="field"><label>Litros/pessoa/dia</label><input name="liters" type="number" min="0.1" step="0.1" value="3" required></div><div class="field"><label>Reserva extra (%)</label><input name="reserve" type="number" min="0" value="20" required></div></div><button class="btn primary full" type="submit">Calcular água</button><div id="${prefix}WaterResult" class="result" hidden></div></form>`}
function waterReserveCalculator(prefix){return `<form id="${prefix}ReserveForm"><div class="form-grid three"><div class="field"><label>Água disponível (L)</label><input name="available" type="number" min="0" step="0.1" required></div><div class="field"><label>Pessoas</label><input name="people" type="number" min="1" value="1" required></div><div class="field"><label>L/pessoa/dia</label><input name="liters" type="number" min="0.1" step="0.1" value="3" required></div></div><button class="btn primary full" type="submit">Calcular duração</button><div id="${prefix}ReserveResult" class="result" hidden></div></form>`}
function renderWater(){view.innerHTML=`${pageHeader("💧","Água","Priorize fonte segura, recipiente limpo e tratamento verificável.")}<section class="panel priority-panel"><h2>Quanto tempo minha reserva dura?</h2>${waterReserveCalculator("water")}</section><section class="panel"><h2>Planejar quantidade</h2>${waterCalculator("main")}</section><section class="panel"><h2>Ordem prática</h2><ol class="protocol"><li>Prefira água potável lacrada ou fornecida por fonte confiável.</li><li>Evite fontes com sinais de esgoto, combustível, químicos ou contaminação industrial.</li><li>Filtrar ou coar remove partículas, mas não torna a água automaticamente segura.</li><li>Na alternativa de fervura já registrada neste guia, filtre/co-e e mantenha a água fervendo pelo período indicado no protocolo do app.</li><li>Armazene água tratada em recipiente limpo e tampado.</li></ol></section><section class="panel"><h2>⚠️ Tratamento químico</h2><div class="notice warning"><strong>O app não calcula dosagem química.</strong> Use apenas a concentração e instruções do rótulo ou fonte oficial confiável.</div></section>`}
function renderShelter(){view.innerHTML=`${pageHeader("🏕️","Abrigo","Reduza exposição sem criar um risco novo.")}<section class="panel"><h2>Escolha do local</h2><ul class="protocol"><li>Evite leitos secos de rios, áreas de enchente e encostas instáveis.</li><li>Observe galhos mortos, rochas, drenagem, vento e rota de saída.</li><li>Evite locais onde fumaça ou gases possam ficar presos.</li></ul></section><section class="panel"><h2>Chuva e vento</h2><ul class="protocol"><li>Incline a cobertura para escoar água.</li><li>Evite bolsas de água na lona.</li><li>Use pontos de ancoragem sólidos e revise a tensão.</li></ul></section><section class="panel"><h2>Frio e chão</h2><ul class="protocol"><li>Isole o corpo do solo.</li><li>Mantenha roupas secas e reduza passagem direta de vento.</li><li>Evite suor excessivo no frio.</li></ul></section><section class="panel"><h2>Calor</h2><ul class="protocol"><li>Priorize sombra e ventilação.</li><li>Evite lona/plástico fechado que vire uma estufa.</li><li>Reduza esforço nos períodos mais quentes.</li></ul></section><section class="panel"><h2>🔥 Fogo</h2><div class="notice danger">Nunca use chama, carvão, fogareiro ou gerador em abrigo fechado ou mal ventilado.</div></section>`}
function renderKnots(){view.innerHTML=`${pageHeader("🪢","Nós e cordas","Consulta rápida para tarefas gerais; não é treinamento de escalada ou resgate.")}<div class="notice warning">Um nó conhecido não transforma uma corda comum em equipamento de segurança de vida.</div><div class="list">${KNOTS.map(k=>`<article class="list-card"><h3>${k.icon} ${k.name}</h3><p><strong>Uso:</strong> ${k.use}</p><div class="meta">⚠️ ${k.warning}</div></article>`).join("")}</div><button class="wide-more" data-nav="recursos"><span>📚</span><div><strong>Meus vídeos/PDFs sobre nós</strong><small>Cadastre onde cada arquivo está salvo</small></div><b>›</b></button>`}

function navigationTools(prefix){return `<details class="tool-details"><summary>Distância e azimute</summary><div class="details-body"><form id="${prefix}DistanceForm"><div class="form-grid"><div class="field"><label>Latitude A</label><input name="lat1" type="number" step="any" required></div><div class="field"><label>Longitude A</label><input name="lon1" type="number" step="any" required></div><div class="field"><label>Latitude B</label><input name="lat2" type="number" step="any" required></div><div class="field"><label>Longitude B</label><input name="lon2" type="number" step="any" required></div></div><button class="btn primary full" type="submit">Calcular</button><div id="${prefix}DistanceResult" class="result" hidden></div></form></div></details><details class="tool-details"><summary>Decimal → graus/minutos/segundos</summary><div class="details-body"><form id="${prefix}DmsForm"><div class="form-grid"><div class="field"><label>Latitude</label><input name="lat" type="number" step="any" min="-90" max="90" required></div><div class="field"><label>Longitude</label><input name="lon" type="number" step="any" min="-180" max="180" required></div></div><button class="btn primary full" type="submit">Converter</button><div id="${prefix}DmsResult" class="result" hidden></div></form></div></details><details class="tool-details"><summary>Graus/minutos/segundos → decimal</summary><div class="details-body"><form id="${prefix}DecimalForm"><div class="form-grid four"><div class="field"><label>Lat °</label><input name="latD" type="number" min="0" max="90" required></div><div class="field"><label>Lat min</label><input name="latM" type="number" min="0" max="59.999" step="any" required></div><div class="field"><label>Lat seg</label><input name="latS" type="number" min="0" max="59.999" step="any" required></div><div class="field"><label>Direção</label><select name="latDir"><option>N</option><option>S</option></select></div><div class="field"><label>Lon °</label><input name="lonD" type="number" min="0" max="180" required></div><div class="field"><label>Lon min</label><input name="lonM" type="number" min="0" max="59.999" step="any" required></div><div class="field"><label>Lon seg</label><input name="lonS" type="number" min="0" max="59.999" step="any" required></div><div class="field"><label>Direção</label><select name="lonDir"><option>W</option><option>E</option></select></div></div><button class="btn primary full" type="submit">Converter</button><div id="${prefix}DecimalResult" class="result" hidden></div></form></div></details>`}
function renderNavigation(){view.innerHTML=`${pageHeader("🧭","Navegação","Coordenadas e orientação para complementar seu MAPS.ME offline.")}<section class="panel priority-panel"><h2>📍 Minha posição</h2>${lastPositionHTML()}<button class="btn primary full" data-gps="nav">Obter posição atual</button><div id="navGpsResult" class="result" hidden></div></section><section class="panel"><h2>🧭 Bússola experimental</h2><div class="compass-wrap"><div class="compass-ring"><span class="mark n">N</span><span class="mark s">S</span><span class="mark e">E</span><span class="mark w">W</span><div id="compassNeedle" class="compass-needle"></div><div class="compass-center"></div></div><div id="compassHeading" class="compass-value">—</div><div id="compassNote" class="compass-note">Sensor ainda não iniciado.</div></div><div class="btn-row"><button class="btn primary" data-action="start-compass">Iniciar bússola</button><button class="btn" data-action="stop-compass">Parar</button></div><div class="notice warning">Experimental: sensores podem ter erro, interferência magnética e exigir calibração. Confirme direção por outros meios.</div></section>${navigationTools("nav")}`}

function energyTools(prefix){return `<section class="panel"><h2>Autonomia pelo consumo</h2><form id="${prefix}RuntimeForm"><div class="form-grid"><div class="field"><label>Bateria atual (%)</label><input name="battery" type="number" min="0.1" max="100" step="0.1" value="80" required></div><div class="field"><label>Consumo (%/h)</label><input name="drain" type="number" min="0.01" step="0.01" value="5" required></div></div><button class="btn primary full" type="submit">Estimar autonomia</button><div id="${prefix}RuntimeResult" class="result" hidden></div></form></section><section class="panel"><h2>Power bank</h2><form id="${prefix}PowerForm"><div class="form-grid"><div class="field"><label>Banco (mAh)</label><input name="pbMah" type="number" min="1" value="20000" required></div><div class="field"><label>Tensão banco (V)</label><input name="pbV" type="number" min="0.1" step="0.01" value="3.7" required></div><div class="field"><label>Eficiência (%)</label><input name="eff" type="number" min="1" max="100" value="80" required></div><div class="field"><label>Celular (mAh)</label><input name="phoneMah" type="number" min="1" value="5000" required></div><div class="field"><label>Tensão celular (V)</label><input name="phoneV" type="number" min="0.1" step="0.01" value="3.85" required></div></div><button class="btn primary full" type="submit">Estimar cargas</button><div id="${prefix}PowerResult" class="result" hidden></div></form></section>`}
function batteryBudget(prefix){return `<form id="${prefix}BudgetForm"><div class="form-grid three"><div class="field"><label>Bateria atual (%)</label><input name="battery" type="number" min="0" max="100" value="60" required></div><div class="field"><label>Precisa durar (h)</label><input name="hours" type="number" min="1" value="36" required></div><div class="field"><label>Reserva final (%)</label><input name="reserve" type="number" min="0" max="100" value="10" required></div></div><button class="btn primary full" type="submit">Criar orçamento</button><div id="${prefix}BudgetResult" class="result" hidden></div></form>`}
function renderEnergy(){view.innerHTML=`${pageHeader("🔋","Energia","Planeje quanto pode gastar e preserve comunicação.")}<section class="panel priority-panel"><h2>Orçamento de bateria</h2>${batteryBudget("energy")}</section><section class="panel"><h2>Economia rápida</h2><ul class="protocol"><li>Reduza brilho e tempo de tela.</li><li>Use modo economia e modo avião quando apropriado.</li><li>Defina horários de checagem de sinal.</li><li>Evite vídeo, jogos e tarefas pesadas.</li><li>Proteja baterias de calor, água e dano físico.</li></ul></section>${energyTools("energy")}<div class="notice warning">Resultados de energia são estimativas; temperatura, cabo, conversão e desgaste alteram a autonomia real.</div>`}

function renderCommunication(){const p=getLastPosition(),coords=p?`${Number(p.lat).toFixed(6)}, ${Number(p.lon).toFixed(6)}`:"";view.innerHTML=`${pageHeader("📻","Comunicação","Mensagem curta, horários definidos e meios redundantes.")}<section class="panel priority-panel"><h2>Gerador de mensagem SOS</h2><form id="sosForm"><div class="form-grid"><div class="field"><label>Pessoas no grupo</label><input name="people" type="number" min="1" value="1" required></div><div class="field"><label>Feridos</label><input name="injured" type="number" min="0" value="0" required></div></div><div class="field"><label>Situação</label><input name="situation" placeholder="Ex.: perdido em área rural" required></div><div class="field"><label>Ajuda necessária</label><input name="need" placeholder="Ex.: resgate / atendimento médico"></div><div class="field"><label>Coordenadas</label><input name="coords" value="${escapeHTML(coords)}" placeholder="Obtenha pelo GPS se necessário"></div><div class="field"><label>Próximo horário de contato</label><input name="next" placeholder="Ex.: 18:00"></div><button class="btn primary full" type="submit">Gerar mensagem</button><div id="sosResult" class="result" hidden></div></form></section><section class="panel"><h2>Formato mínimo</h2><div class="template-block"><strong>QUEM</strong> · <strong>ONDE</strong> · <strong>CONDIÇÃO</strong> · <strong>PRECISO</strong> · <strong>PRÓXIMO CONTATO</strong></div></section><section class="panel"><h2>📱 Celular / SMS</h2><p>Evite tentativas contínuas; mensagens curtas e horários definidos ajudam a preservar bateria.</p></section><section class="panel"><h2>📻 Rádio / Meshtastic / Bitchat</h2><p>Use apenas equipamentos e redes já configurados e testados. Mantenha um ponto de encontro físico como redundância.</p></section><section class="panel"><h2>… --- … SOS em Morse</h2><p>Três sinais curtos, três longos e três curtos.</p></section><button class="wide-more" data-nav="plano"><span>🗺️</span><div><strong>Plano de comunicação</strong><small>Canais, horários e ponto de encontro</small></div><b>›</b></button>`}

function renderChecklist(){const items=getChecklist(),done=items.filter(i=>i.done).length,percent=items.length?Math.round(done/items.length*100):0;view.innerHTML=`${pageHeader("🎒","Checklist","Itens salvos localmente neste aparelho.")}<section class="panel"><div class="status-line"><span><strong>${done}</strong> de <strong>${items.length}</strong> marcados</span><span class="pill">${percent}%</span></div><div class="progress"><span style="width:${percent}%"></span></div></section><section class="panel"><form id="checklistAddForm"><div class="form-grid"><div class="field"><label>Item</label><input name="text" maxlength="100" required></div><div class="field"><label>Categoria</label><input name="category" maxlength="60"></div></div><button class="btn primary full" type="submit">Adicionar</button></form></section><div class="list">${items.map(i=>`<article class="check-item ${i.done?"done":""}"><input type="checkbox" data-check="${escapeHTML(i.id)}" ${i.done?"checked":""}><div class="check-content"><strong>${escapeHTML(i.text)}</strong><small>${escapeHTML(i.category||"Sem categoria")}</small></div><div class="mini-actions"><button class="mini-button" data-edit-check="${escapeHTML(i.id)}">✎</button><button class="mini-button" data-delete-check="${escapeHTML(i.id)}">🗑</button></div></article>`).join("")||`<div class="empty">Nenhum item.</div>`}</div>`}
function renderContacts(){const c=getContacts();view.innerHTML=`${pageHeader("📞","Contatos","Contatos personalizados ficam somente neste aparelho.")}<section class="panel">${emergencyCalls()}</section><section class="panel"><form id="contactAddForm"><div class="form-grid"><div class="field"><label>Nome</label><input name="name" maxlength="80" required></div><div class="field"><label>Telefone</label><input name="phone" inputmode="tel" maxlength="40" required></div></div><div class="field"><label>Observação</label><input name="note" maxlength="120"></div><button class="btn primary full" type="submit">Salvar contato</button></form></section><div class="list">${c.map(x=>`<article class="list-card contact-card"><div><div class="contact-name">${escapeHTML(x.name)}</div><div class="contact-number">${escapeHTML(x.phone)}</div>${x.note?`<div class="meta">${escapeHTML(x.note)}</div>`:""}<div class="btn-row"><button class="btn" data-edit-contact="${escapeHTML(x.id)}">Editar</button><button class="btn danger" data-delete-contact="${escapeHTML(x.id)}">Excluir</button></div></div><a class="call-circle" href="tel:${escapeHTML(x.phone)}">📞</a></article>`).join("")||`<div class="empty">Nenhum contato personalizado.</div>`}</div>`}
function renderPlan(){const p=getPlan();view.innerHTML=`${pageHeader("🗺️","Plano de emergência","Defina antes: onde encontrar o grupo e quando tentar comunicação.")}<form id="planForm" class="panel"><div class="field"><label>Ponto de encontro principal</label><input name="meeting" value="${escapeHTML(p.meeting)}"></div><div class="field"><label>Ponto alternativo</label><input name="backupMeeting" value="${escapeHTML(p.backupMeeting)}"></div><div class="field"><label>Rádio / canal / frequência</label><input name="radio" value="${escapeHTML(p.radio)}"></div><div class="field"><label>Horários de contato/escuta</label><input name="checkin" value="${escapeHTML(p.checkin)}" placeholder="Ex.: 08:00, 14:00 e 20:00"></div><div class="field"><label>Método alternativo</label><input name="backupMethod" value="${escapeHTML(p.backupMethod)}" placeholder="Ex.: SMS → rádio → ponto de encontro"></div><div class="field"><label>Mensagem padrão</label><textarea name="message">${escapeHTML(p.message)}</textarea></div><div class="field"><label>Observações</label><textarea name="notes">${escapeHTML(p.notes)}</textarea></div><button class="btn primary full" type="submit">Salvar plano localmente</button></form>`}
function renderICE(){const i=getICE();view.innerHTML=`${pageHeader("🪪","Ficha ICE","Opcional. Preencha apenas o que você quer deixar disponível neste aparelho.")}<div class="notice warning">Informações desta ficha são referências declaradas pelo usuário; não substituem avaliação médica.</div><form id="iceForm" class="panel"><div class="form-grid"><div class="field"><label>Nome</label><input name="name" value="${escapeHTML(i.name)}"></div><div class="field"><label>Data de nascimento</label><input name="birthDate" type="date" value="${escapeHTML(i.birthDate)}"></div><div class="field"><label>Contato ICE</label><input name="iceName" value="${escapeHTML(i.iceName)}"></div><div class="field"><label>Telefone ICE</label><input name="icePhone" inputmode="tel" value="${escapeHTML(i.icePhone)}"></div><div class="field"><label>Tipo sanguíneo (se souber)</label><input name="bloodType" value="${escapeHTML(i.bloodType)}"></div><div class="field"><label>Alergias declaradas</label><input name="allergies" value="${escapeHTML(i.allergies)}"></div><div class="field"><label>Medicamentos declarados</label><input name="medications" value="${escapeHTML(i.medications)}"></div><div class="field"><label>Condições / observações</label><input name="conditions" value="${escapeHTML(i.conditions)}"></div></div><div class="field"><label>Outras notas</label><textarea name="notes">${escapeHTML(i.notes)}</textarea></div><button class="btn primary full" type="submit">Salvar ficha neste aparelho</button></form>`}

function renderJournal(){const entries=getJournal().sort((a,b)=>String(b.timestamp).localeCompare(String(a.timestamp)));view.innerHTML=`${pageHeader("📝","Diário da ocorrência","Registre uma linha do tempo simples com horário automático.")}<section class="panel"><form id="journalForm"><div class="form-grid"><div class="field"><label>Tipo</label><select name="type"><option>Geral</option><option>Localização</option><option>Saúde</option><option>Comunicação</option><option>Energia</option><option>Água</option></select></div><div class="field"><label><input name="withLocation" type="checkbox"> anexar última posição</label></div></div><div class="field"><label>Registro</label><textarea name="text" required placeholder="Ex.: água começou a subir na rua"></textarea></div><button class="btn primary full" type="submit">Registrar agora</button></form></section><div class="timeline">${entries.map(e=>`<article class="timeline-item"><div class="timeline-time">${escapeHTML(e.type)} · ${formatWhen(e.timestamp)}</div><p>${escapeHTML(e.text)}</p>${e.position?`<div class="timeline-location">📍 ${Number(e.position.lat).toFixed(6)}, ${Number(e.position.lon).toFixed(6)}</div>`:""}<button class="text-button" data-delete-journal="${e.id}">Excluir</button></article>`).join("")||`<div class="empty">Nenhum registro ainda.</div>`}</div>`}
function inventoryBadges(item){const s=inventoryStatus(item),parts=[];if(s.low)parts.push(`<span class="attention-badge">estoque baixo</span>`);if(s.expired)parts.push(`<span class="attention-badge danger-badge">vencido</span>`);else if(s.expiring)parts.push(`<span class="attention-badge">vence em ${s.dd} dia(s)</span>`);return parts.join(" ")}
function renderInventory(){const items=getInventory();view.innerHTML=`${pageHeader("📦","Estoque de emergência","Quantidades, nível mínimo e validade. Tudo local.")}<section class="panel"><form id="inventoryForm"><div class="form-grid"><div class="field"><label>Item</label><input name="name" required></div><div class="field"><label>Categoria</label><input name="category"></div><div class="field"><label>Quantidade</label><input name="quantity" type="number" min="0" step="any" value="1" required></div><div class="field"><label>Unidade</label><input name="unit" placeholder="L, un, kg..."></div><div class="field"><label>Mínimo desejado</label><input name="minimum" type="number" min="0" step="any" value="0"></div><div class="field"><label>Validade (opcional)</label><input name="expiry" type="date"></div></div><button class="btn primary full" type="submit">Adicionar ao estoque</button></form></section><div class="list">${items.map(i=>{const s=inventoryStatus(i);return `<article class="list-card inventory-card ${s.expired?"expired":s.low?"low":""}"><h3>${escapeHTML(i.name)}</h3><p>${escapeHTML(i.category||"Sem categoria")}${i.expiry?` · validade ${formatDate(i.expiry)}`:""}</p><div>${inventoryBadges(i)}</div><div class="quantity-row"><button data-inventory-delta="-1" data-id="${i.id}">−</button><div class="quantity-value">${Number(i.quantity)} ${escapeHTML(i.unit||"")}</div><button data-inventory-delta="1" data-id="${i.id}">+</button></div><div class="btn-row"><button class="btn" data-edit-inventory="${i.id}">Editar</button><button class="btn danger" data-delete-inventory="${i.id}">Excluir</button></div></article>`}).join("")||`<div class="empty">Nenhum item cadastrado.</div>`}</div>`}
function renderMaintenance(){const items=getMaintenance();view.innerHTML=`${pageHeader("🛠️","Validades e manutenção","Lembretes locais para testar, recarregar ou substituir equipamentos.")}<section class="panel"><form id="maintenanceForm"><div class="form-grid"><div class="field"><label>Equipamento / tarefa</label><input name="name" required></div><div class="field"><label>Próxima revisão</label><input name="due" type="date" required></div></div><div class="field"><label>Observação</label><input name="note" placeholder="Ex.: testar rádio e recarregar bateria"></div><button class="btn primary full" type="submit">Adicionar revisão</button></form></section><div class="list">${items.map(i=>{const s=maintenanceStatus(i);return `<article class="list-card maintenance-card ${s.due?"due":""}"><h3>${escapeHTML(i.name)}</h3><p>Próxima: ${formatDate(i.due)}${i.note?` · ${escapeHTML(i.note)}`:""}</p>${s.due?`<span class="attention-badge">revisão vencida/hoje</span>`:s.soon?`<span class="attention-badge">em ${s.dd} dia(s)</span>`:""}<div class="btn-row"><button class="btn" data-edit-maintenance="${i.id}">Editar</button><button class="btn danger" data-delete-maintenance="${i.id}">Excluir</button></div></article>`}).join("")||`<div class="empty">Nenhuma revisão cadastrada.</div>`}</div>`}
function renderResources(){const items=getResources();view.innerHTML=`${pageHeader("📚","Meus recursos offline","Um índice rápido para lembrar onde estão seus materiais. A PWA não abre automaticamente arquivos privados do Android.")}<section class="panel"><h2>Recursos já usados pelo seu sistema</h2><div class="list"><div class="list-card builtin-resource"><span>🗺️</span><div><strong>MAPS.ME</strong><small>Mapa e navegação detalhada offline</small></div></div><div class="list-card builtin-resource"><span>📚</span><div><strong>Kiwix</strong><small>Wikipédia, conteúdos médicos e referências offline</small></div></div><div class="list-card builtin-resource"><span>📄</span><div><strong>PDFs</strong><small>Manuais detalhados de sobrevivência</small></div></div><div class="list-card builtin-resource"><span>🎬</span><div><strong>Vídeos offline</strong><small>Demonstrações e treinamentos</small></div></div></div></section><section class="panel"><h2>Cadastrar referência</h2><form id="resourceForm"><div class="form-grid"><div class="field"><label>Tipo</label><select name="type"><option>PDF</option><option>Vídeo</option><option>Kiwix</option><option>Mapa</option><option>Nota</option><option>App</option><option>Outro</option></select></div><div class="field"><label>Nome</label><input name="name" required></div></div><div class="field"><label>Onde encontrar / nome do arquivo</label><input name="reference" placeholder="Ex.: pasta Sobrevivência/PDFs/agua.pdf"></div><div class="field"><label>Observação</label><input name="note"></div><button class="btn primary full" type="submit">Salvar referência</button></form></section><div class="list">${items.map(i=>`<article class="list-card"><h3>${escapeHTML(i.type)} · ${escapeHTML(i.name)}</h3><p>${escapeHTML(i.reference||"Sem localização anotada")}</p>${i.note?`<div class="meta">${escapeHTML(i.note)}</div>`:""}<div class="btn-row"><button class="btn" data-edit-resource="${i.id}">Editar</button><button class="btn danger" data-delete-resource="${i.id}">Excluir</button></div></article>`).join("")||`<div class="empty">Nenhuma referência personalizada.</div>`}</div>`}

function environmentalCalculators(){const lp=getLastPosition();return `<details class="tool-details"><summary>☀️ Índice de calor</summary><div class="details-body"><form id="heatForm"><div class="form-grid"><div class="field"><label>Temperatura (°C)</label><input name="temp" type="number" step="0.1" required></div><div class="field"><label>Umidade relativa (%)</label><input name="rh" type="number" min="0" max="100" required></div></div><button class="btn primary full" type="submit">Calcular</button><div id="heatResult" class="result" hidden></div></form><div class="notice warning">Índice de calor é uma estimativa para sombra; sol direto e outras condições podem aumentar o estresse térmico.</div></div></details><details class="tool-details"><summary>❄️ Sensação térmica pelo vento</summary><div class="details-body"><form id="windChillForm"><div class="form-grid"><div class="field"><label>Temperatura (°C)</label><input name="temp" type="number" step="0.1" required></div><div class="field"><label>Vento (km/h)</label><input name="wind" type="number" min="0" step="0.1" required></div></div><button class="btn primary full" type="submit">Calcular</button><div id="windChillResult" class="result" hidden></div></form></div></details><details class="tool-details"><summary>🌅 Horas aproximadas de luz do dia</summary><div class="details-body"><form id="daylightForm"><div class="form-grid"><div class="field"><label>Data</label><input name="date" type="date" value="${localDateValue()}" required></div><div class="field"><label>Latitude</label><input name="lat" type="number" min="-90" max="90" step="any" value="${lp?Number(lp.lat).toFixed(6):""}" required></div></div><button class="btn primary full" type="submit">Estimar duração</button><div id="daylightResult" class="result" hidden></div></form><div class="notice">Estimativa astronômica aproximada de duração do dia; relevo, horizonte e condições locais alteram a luz útil real.</div></div></details>`}
function renderCalculators(){view.innerHTML=`${pageHeader("🧮","Calculadoras","Ferramentas locais. As mais usadas ficam no topo; as demais ficam recolhidas.")}<section class="panel priority-panel"><h2>💧 Duração da reserva de água</h2>${waterReserveCalculator("calc")}</section><details class="tool-details"><summary>💧 Planejar quantidade de água</summary><div class="details-body">${waterCalculator("calcPlan")}</div></details><details class="tool-details"><summary>🔋 Orçamento de bateria</summary><div class="details-body">${batteryBudget("calc")}</div></details><details class="tool-details"><summary>🔋 Autonomia e power bank</summary><div class="details-body">${energyTools("calcEnergy")}</div></details>${environmentalCalculators()}<details class="tool-details"><summary>⚡ Watts-hora (Wh)</summary><div class="details-body"><form id="whForm"><div class="form-grid"><div class="field"><label>Tensão (V)</label><input name="volts" type="number" min="0.01" step="any" required></div><div class="field"><label>Capacidade (mAh)</label><input name="mah" type="number" min="1" step="any" required></div></div><button class="btn primary full" type="submit">Calcular Wh</button><div id="whResult" class="result" hidden></div></form></div></details><details class="tool-details"><summary>🚶 Tempo de deslocamento</summary><div class="details-body"><form id="travelForm"><div class="form-grid"><div class="field"><label>Distância (km)</label><input name="distance" type="number" min="0" step="any" required></div><div class="field"><label>Velocidade média (km/h)</label><input name="speed" type="number" min="0.1" step="any" value="4" required></div></div><button class="btn primary full" type="submit">Estimar tempo</button><div id="travelResult" class="result" hidden></div></form></div></details><details class="tool-details"><summary>📏 Conversão de unidades</summary><div class="details-body"><form id="unitForm"><div class="form-grid"><div class="field"><label>Valor</label><input name="value" type="number" step="any" required></div><div class="field"><label>Conversão</label><select name="conversion"><option value="km-mi">km → milhas</option><option value="mi-km">milhas → km</option><option value="m-ft">metros → pés</option><option value="ft-m">pés → metros</option><option value="l-gal">litros → galões US</option><option value="gal-l">galões US → litros</option><option value="c-f">°C → °F</option><option value="f-c">°F → °C</option><option value="kg-lb">kg → lb</option><option value="lb-kg">lb → kg</option></select></div></div><button class="btn primary full" type="submit">Converter</button><div id="unitResult" class="result" hidden></div></form></div></details><details class="tool-details"><summary>🧭 Coordenadas, distância e azimute</summary><div class="details-body">${navigationTools("calcNav")}</div></details><details class="tool-details"><summary>🪢 Comprimento estimado de corda</summary><div class="details-body"><form id="ropeForm"><div class="form-grid"><div class="field"><label>Nº de trechos</label><input name="segments" type="number" min="1" value="1" required></div><div class="field"><label>Comprimento/trecho (m)</label><input name="length" type="number" min="0.01" step="any" required></div><div class="field"><label>Margem extra (%)</label><input name="margin" type="number" min="0" value="20" required></div><div class="field"><label>Extra nós/ajustes (m)</label><input name="extra" type="number" min="0" step="any" value="0" required></div></div><button class="btn primary full" type="submit">Estimar</button><div id="ropeResult" class="result" hidden></div></form><div class="notice warning">Planeja comprimento; não calcula resistência ou segurança para escalada/resgate.</div></div></details>`}

function renderMore(){const settings=getSettings();view.innerHTML=`${pageHeader("☰","Todos os recursos","Completo por dentro, mas organizado para você não procurar demais em uma emergência.")}<section class="panel"><div class="setting-row"><div><strong>🔠 Texto grande</strong><div class="meta">Aumenta fontes e controles</div></div><button class="toggle ${settings.textLarge?"on":""}" data-action="toggle-text">${settings.textLarge?"ATIVO":"NORMAL"}</button></div></section><div class="card-grid">${MODULES.filter(m=>!["checklist","calculadoras"].includes(m[0])).map(m=>resourceCard(m[0],m[1],m[2],m[3])).join("")}</div>`}
function renderSources(){view.innerHTML=`${pageHeader("ℹ️","Fontes e limites","O app prioriza consulta rápida; orientação profissional e protocolos oficiais têm prioridade.")}<section class="panel"><h2>Limites</h2><ul class="protocol"><li>Não substitui médico, bombeiro, Defesa Civil ou treinamento técnico.</li><li>Não calcula dose química para tratamento de água.</li><li>Não certifica nó, corda ou ancoragem.</li><li>Bússola e GPS podem ter erro; confirme por meios redundantes.</li><li>Cálculos ambientais e de energia são estimativas.</li></ul></section><section class="panel"><h2>Referências da V3</h2><ul class="protocol"><li>Serviços públicos brasileiros de emergência.</li><li>Orientações de saúde e primeiros socorros registradas na versão anterior.</li><li>Fórmulas meteorológicas reconhecidas para índice de calor e sensação térmica pelo vento.</li></ul></section>`}

function backupPayload(){return {app:"Sobrevivência Offline",version:3,schema:CURRENT_SCHEMA,created:new Date().toISOString(),checklist:getChecklist(),contacts:getContacts(),plan:getPlan(),favorites:getFavorites(),lastPosition:getLastPosition(),ice:getICE(),journal:getJournal(),inventory:getInventory(),maintenance:getMaintenance(),resources:getResources(),settings:getSettings()}}
function renderData(){view.innerHTML=`${pageHeader("💾","Backup e autoteste","Confirme se o app está pronto para funcionar sem rede e mantenha um backup local.")}<section class="panel priority-panel"><h2>Autoteste offline</h2><button class="btn primary full" data-action="self-test">Executar teste</button><div id="selfTestResult" style="margin-top:10px"></div></section><section class="panel"><h2>Estado dos dados</h2><div class="status-line"><span>Schema</span><span class="pill">V${CURRENT_SCHEMA}</span></div><div class="status-line"><span>Checklist</span><span class="pill">${getChecklist().length}</span></div><div class="status-line"><span>Contatos</span><span class="pill">${getContacts().length}</span></div><div class="status-line"><span>Diário</span><span class="pill">${getJournal().length}</span></div><div class="status-line"><span>Estoque</span><span class="pill">${getInventory().length}</span></div></section><section class="panel"><h2>Backup completo</h2><p>Inclui todos os dados da V3 em um único JSON. Backups antigos V1/V2 continuam importáveis.</p><div class="btn-row"><button class="btn primary" data-action="export">Exportar</button><button class="btn" data-action="import">Importar</button></div></section><section class="panel"><h2>Limpar tudo</h2><button class="btn danger" data-action="clear">Apagar dados locais</button></section>`}

function stopCompass(){if(compassHandler&&compassEventName)window.removeEventListener(compassEventName,compassHandler,true);compassHandler=null;compassEventName=null}
function renderView(name){stopCompass();currentViewName=name;const map={home:renderHome,"modo-emergencia":renderEmergencyMode,emergencias:renderEmergencies,agua:renderWater,abrigo:renderShelter,nos:renderKnots,navegacao:renderNavigation,energia:renderEnergy,comunicacao:renderCommunication,checklist:renderChecklist,calculadoras:renderCalculators,contatos:renderContacts,plano:renderPlan,ice:renderICE,diario:renderJournal,estoque:renderInventory,manutencao:renderMaintenance,recursos:renderResources,dados:renderData,fontes:renderSources,mais:renderMore};(map[name]||renderHome)();const more=["agua","abrigo","nos","navegacao","energia","comunicacao","contatos","plano","ice","diario","estoque","manutencao","recursos","dados","fontes"];document.querySelectorAll(".nav-button").forEach(b=>b.classList.toggle("active",b.dataset.nav===name||(b.dataset.nav==="mais"&&more.includes(name))));window.scrollTo(0,0)}

const radians=v=>v*Math.PI/180, degrees=v=>v*180/Math.PI;
function distanceBearing(lat1,lon1,lat2,lon2){const R=6371.0088,p1=radians(lat1),p2=radians(lat2),dLat=radians(lat2-lat1),dLon=radians(lon2-lon1),a=Math.sin(dLat/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dLon/2)**2,c=2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a)),y=Math.sin(dLon)*Math.cos(p2),x=Math.cos(p1)*Math.sin(p2)-Math.sin(p1)*Math.cos(p2)*Math.cos(dLon);return {distance:R*c,bearing:(degrees(Math.atan2(y,x))+360)%360}}
function decimalToDMS(value,lat){const a=Math.abs(value),d=Math.floor(a),mf=(a-d)*60,m=Math.floor(mf),s=(mf-m)*60,dir=lat?(value>=0?"N":"S"):(value>=0?"E":"W");return `${d}° ${m}' ${s.toFixed(2)}" ${dir}`}
function dmsToDecimal(d,m,s,dir){let v=Number(d)+Number(m)/60+Number(s)/3600;if(dir==="S"||dir==="W")v*=-1;return v}
function cardinal(h){const names=["N","NE","L","SE","S","SO","O","NO"];return names[Math.round(h/45)%8]}
async function getGPS(prefix){const result=document.getElementById(prefix+"GpsResult");if(result){result.hidden=false;result.innerHTML="<small>Obtendo posição…</small>"}if(!navigator.geolocation){if(result)result.innerHTML="<strong>GPS indisponível.</strong>";return}navigator.geolocation.getCurrentPosition(pos=>{const p={lat:pos.coords.latitude,lon:pos.coords.longitude,accuracy:pos.coords.accuracy,timestamp:new Date().toISOString()};saveJSON(STORAGE.lastPosition,p);const text=`${p.lat.toFixed(6)}, ${p.lon.toFixed(6)}`;if(result)result.innerHTML=`<strong class="coord">${text}</strong><small>Precisão informada: ±${Math.round(p.accuracy)} m · posição salva localmente.</small><button class="btn" data-copy="${text}">Copiar</button>`;showToast("Última posição atualizada")},err=>{if(result)result.innerHTML=`<strong>Não foi possível obter GPS.</strong><small>${err.message}</small>`},{enableHighAccuracy:true,timeout:20000,maximumAge:15000})}
async function copyText(text){try{await navigator.clipboard.writeText(text);showToast("Copiado")}catch{showToast("Não foi possível copiar automaticamente")}}
async function startCompass(){const heading=document.getElementById("compassHeading"),needle=document.getElementById("compassNeedle"),note=document.getElementById("compassNote");if(!heading||!needle)return;try{if(typeof DeviceOrientationEvent!=="undefined"&&typeof DeviceOrientationEvent.requestPermission==="function"){const p=await DeviceOrientationEvent.requestPermission();if(p!=="granted")throw new Error("Permissão negada")}stopCompass();compassEventName="ondeviceorientationabsolute" in window?"deviceorientationabsolute":"deviceorientation";compassHandler=e=>{let h=null;if(typeof e.webkitCompassHeading==="number")h=e.webkitCompassHeading;else if(typeof e.alpha==="number")h=(360-e.alpha+360)%360;if(h===null)return;heading.textContent=`${h.toFixed(0)}° ${cardinal(h)}`;needle.style.transform=`translate(-50%,0) rotate(${h}deg)`;note.textContent="Compare com mapa e referências físicas."};window.addEventListener(compassEventName,compassHandler,true);note.textContent="Aguardando sensor…"}catch(e){note.textContent="Bússola indisponível: "+e.message}}

function calculateWater(form,id){const d=new FormData(form),base=Number(d.get("people"))*Number(d.get("days"))*Number(d.get("liters")),reserve=Number(d.get("reserve")),total=base*(1+reserve/100),r=document.getElementById(id);r.hidden=false;r.innerHTML=`<strong>${total.toFixed(1)} L</strong><small>Base: ${base.toFixed(1)} L + ${reserve}% de reserva.</small>`}
function calculateWaterReserve(form,id){const d=new FormData(form),a=Number(d.get("available")),p=Number(d.get("people")),l=Number(d.get("liters")),days=a/(p*l),r=document.getElementById(id);r.hidden=false;r.innerHTML=`<strong>≈ ${days.toFixed(2)} dias</strong><small>Consumo planejado: ${(p*l).toFixed(1)} L/dia.</small>`}
function calculateRuntime(form,id){const d=new FormData(form),time=Number(d.get("battery"))/Number(d.get("drain")),h=Math.floor(time),m=Math.round((time-h)*60),r=document.getElementById(id);r.hidden=false;r.innerHTML=`<strong>≈ ${h} h ${m} min</strong><small>Estimativa com consumo constante.</small>`}
function calculateBudget(form,id){const d=new FormData(form),battery=Number(d.get("battery")),hours=Number(d.get("hours")),reserve=Number(d.get("reserve")),usable=Math.max(0,battery-reserve),perHour=usable/hours,r=document.getElementById(id);r.hidden=false;r.innerHTML=`<strong>Até ≈ ${perHour.toFixed(2)}% por hora</strong><small>Energia utilizável: ${usable.toFixed(1)}%. Em 6 h: ≈ ${(perHour*6).toFixed(1)}%. Preserve a reserva final de ${reserve}%.</small>`}
function calculatePower(form,id){const d=new FormData(form),pbWh=Number(d.get("pbMah"))*Number(d.get("pbV"))/1000,usable=pbWh*(Number(d.get("eff"))/100),phoneWh=Number(d.get("phoneMah"))*Number(d.get("phoneV"))/1000,charges=usable/phoneWh,r=document.getElementById(id);r.hidden=false;r.innerHTML=`<strong>≈ ${charges.toFixed(2)} cargas</strong><small>Energia utilizável estimada: ${usable.toFixed(1)} Wh.</small>`}
function calculateDistance(form,prefix){const d=new FormData(form),a=distanceBearing(Number(d.get("lat1")),Number(d.get("lon1")),Number(d.get("lat2")),Number(d.get("lon2"))),r=document.getElementById(prefix+"DistanceResult");r.hidden=false;r.innerHTML=`<strong>${a.distance.toFixed(3)} km</strong><small>Azimute inicial: ${a.bearing.toFixed(1)}°. Linha geodésica, não rota por estrada/trilha.</small>`}
function calculateDMS(form,prefix){const d=new FormData(form),r=document.getElementById(prefix+"DmsResult");r.hidden=false;r.innerHTML=`<strong class="coord">${decimalToDMS(Number(d.get("lat")),true)}</strong><small class="coord">${decimalToDMS(Number(d.get("lon")),false)}</small>`}
function calculateDecimal(form,prefix){const d=new FormData(form),lat=dmsToDecimal(d.get("latD"),d.get("latM"),d.get("latS"),d.get("latDir")),lon=dmsToDecimal(d.get("lonD"),d.get("lonM"),d.get("lonS"),d.get("lonDir")),r=document.getElementById(prefix+"DecimalResult");r.hidden=false;r.innerHTML=`<strong class="coord">${lat.toFixed(6)}, ${lon.toFixed(6)}</strong>`}
function calculateWh(form){const d=new FormData(form),wh=Number(d.get("volts"))*Number(d.get("mah"))/1000,r=document.getElementById("whResult");r.hidden=false;r.innerHTML=`<strong>${wh.toFixed(2)} Wh</strong>`}
function calculateTravel(form){const d=new FormData(form),hours=Number(d.get("distance"))/Number(d.get("speed")),h=Math.floor(hours),m=Math.round((hours-h)*60),r=document.getElementById("travelResult");r.hidden=false;r.innerHTML=`<strong>≈ ${h} h ${m} min</strong><small>Terreno, peso, clima, pausas e condição física podem alterar muito o tempo real.</small>`}
function calculateRope(form){const d=new FormData(form),base=Number(d.get("segments"))*Number(d.get("length")),total=base*(1+Number(d.get("margin"))/100)+Number(d.get("extra")),r=document.getElementById("ropeResult");r.hidden=false;r.innerHTML=`<strong>${total.toFixed(2)} m</strong><small>Base ${base.toFixed(2)} m + margem e extra informados.</small>`}
function calculateUnit(form){const d=new FormData(form),v=Number(d.get("value")),t=d.get("conversion");let a=0,u="";switch(t){case"km-mi":a=v*.6213711922;u="mi";break;case"mi-km":a=v/.6213711922;u="km";break;case"m-ft":a=v*3.280839895;u="ft";break;case"ft-m":a=v/3.280839895;u="m";break;case"l-gal":a=v*.2641720524;u="gal US";break;case"gal-l":a=v/.2641720524;u="L";break;case"c-f":a=v*9/5+32;u="°F";break;case"f-c":a=(v-32)*5/9;u="°C";break;case"kg-lb":a=v*2.2046226218;u="lb";break;case"lb-kg":a=v/2.2046226218;u="kg";break}const r=document.getElementById("unitResult");r.hidden=false;r.innerHTML=`<strong>${a.toFixed(3)} ${u}</strong>`}
function heatIndexC(tempC,rh){const T=tempC*9/5+32;let simple=.5*(T+61+((T-68)*1.2)+(rh*.094));simple=(simple+T)/2;let hi=simple;if(simple>=80){hi=-42.379+2.04901523*T+10.14333127*rh-.22475541*T*rh-.00683783*T*T-.05481717*rh*rh+.00122874*T*T*rh+.00085282*T*rh*rh-.00000199*T*T*rh*rh;if(rh<13&&T>=80&&T<=112)hi-=((13-rh)/4)*Math.sqrt((17-Math.abs(T-95))/17);else if(rh>85&&T>=80&&T<=87)hi+=((rh-85)/10)*((87-T)/5)}return (hi-32)*5/9}
function calculateHeat(form){const d=new FormData(form),t=Number(d.get("temp")),rh=Number(d.get("rh")),hi=heatIndexC(t,rh),r=document.getElementById("heatResult");r.hidden=false;r.innerHTML=`<strong>≈ ${hi.toFixed(1)} °C</strong><small>Estimativa de índice de calor em sombra.</small>`}
function calculateWindChill(form){const d=new FormData(form),t=Number(d.get("temp")),v=Number(d.get("wind")),r=document.getElementById("windChillResult");r.hidden=false;if(t>10||v<=4.8){r.innerHTML=`<strong>Fora da faixa principal</strong><small>A fórmula de sensação térmica pelo vento é definida para temperatura ≤10 °C e vento >4,8 km/h.</small>`;return}const wc=13.12+.6215*t-11.37*Math.pow(v,.16)+.3965*t*Math.pow(v,.16);r.innerHTML=`<strong>≈ ${wc.toFixed(1)} °C</strong>`}
function calculateDaylight(form){const d=new FormData(form),date=new Date(d.get("date")+"T12:00:00"),lat=radians(Number(d.get("lat"))),n=Math.floor((Date.UTC(date.getFullYear(),date.getMonth(),date.getDate())-Date.UTC(date.getFullYear(),0,0))/86400000),decl=radians(-23.44*Math.cos(radians((360/365)*(n+10)))),x=-Math.tan(lat)*Math.tan(decl);let hours=x>=1?0:x<=-1?24:24*Math.acos(x)/Math.PI;const r=document.getElementById("daylightResult");r.hidden=false;r.innerHTML=`<strong>≈ ${hours.toFixed(1)} h de luz</strong><small>Estimativa astronômica de duração entre nascer e pôr do Sol.</small>`}

function editChecklist(id){const i=getChecklist().find(x=>x.id===id);if(!i)return;openModal("Editar item",`<form id="checklistEditForm" data-id="${id}"><div class="field"><label>Item</label><input name="text" value="${escapeHTML(i.text)}" required></div><div class="field"><label>Categoria</label><input name="category" value="${escapeHTML(i.category||"")}"></div><button class="btn primary full">Salvar</button></form>`)}
function editContact(id){const c=getContacts().find(x=>x.id===id);if(!c)return;openModal("Editar contato",`<form id="contactEditForm" data-id="${id}"><div class="field"><label>Nome</label><input name="name" value="${escapeHTML(c.name)}" required></div><div class="field"><label>Telefone</label><input name="phone" value="${escapeHTML(c.phone)}" required></div><div class="field"><label>Observação</label><input name="note" value="${escapeHTML(c.note||"")}"></div><button class="btn primary full">Salvar</button></form>`)}
function editInventory(id){const i=getInventory().find(x=>x.id===id);if(!i)return;openModal("Editar estoque",`<form id="inventoryEditForm" data-id="${id}"><div class="field"><label>Item</label><input name="name" value="${escapeHTML(i.name)}" required></div><div class="form-grid"><div class="field"><label>Quantidade</label><input name="quantity" type="number" min="0" step="any" value="${i.quantity}"></div><div class="field"><label>Unidade</label><input name="unit" value="${escapeHTML(i.unit||"")}"></div><div class="field"><label>Mínimo</label><input name="minimum" type="number" min="0" step="any" value="${i.minimum||0}"></div><div class="field"><label>Validade</label><input name="expiry" type="date" value="${escapeHTML(i.expiry||"")}"></div></div><div class="field"><label>Categoria</label><input name="category" value="${escapeHTML(i.category||"")}"></div><button class="btn primary full">Salvar</button></form>`)}
function editMaintenance(id){const i=getMaintenance().find(x=>x.id===id);if(!i)return;openModal("Editar revisão",`<form id="maintenanceEditForm" data-id="${id}"><div class="field"><label>Equipamento/tarefa</label><input name="name" value="${escapeHTML(i.name)}" required></div><div class="field"><label>Próxima revisão</label><input name="due" type="date" value="${escapeHTML(i.due)}" required></div><div class="field"><label>Observação</label><input name="note" value="${escapeHTML(i.note||"")}"></div><button class="btn primary full">Salvar</button></form>`)}
function editResource(id){const i=getResources().find(x=>x.id===id);if(!i)return;openModal("Editar referência",`<form id="resourceEditForm" data-id="${id}"><div class="field"><label>Tipo</label><input name="type" value="${escapeHTML(i.type)}" required></div><div class="field"><label>Nome</label><input name="name" value="${escapeHTML(i.name)}" required></div><div class="field"><label>Onde encontrar</label><input name="reference" value="${escapeHTML(i.reference||"")}"></div><div class="field"><label>Observação</label><input name="note" value="${escapeHTML(i.note||"")}"></div><button class="btn primary full">Salvar</button></form>`)}

function exportBackup(){const data=backupPayload(),blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`sobrevivencia-backup-v3-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);showToast("Backup completo exportado")}
async function importBackup(file){try{const b=JSON.parse(await file.text());if(!b||typeof b!=="object")throw new Error();if(!confirm("Importar este backup e substituir os dados correspondentes?"))return;const mappings=[["checklist",STORAGE.checklist],["contacts",STORAGE.contacts],["plan",STORAGE.plan],["favorites",STORAGE.favorites],["lastPosition",STORAGE.lastPosition],["ice",STORAGE.ice],["journal",STORAGE.journal],["inventory",STORAGE.inventory],["maintenance",STORAGE.maintenance],["resources",STORAGE.resources],["settings",STORAGE.settings]];for(const [field,key] of mappings)if(Object.prototype.hasOwnProperty.call(b,field))saveJSON(key,b[field]);migrateData();applySettings();showToast("Backup importado");renderView("dados")}catch{showToast("Backup inválido ou incompatível")}finally{importInput.value=""}}
function clearData(){if(!confirm("Apagar TODOS os dados locais do Sobrevivência Offline?"))return;Object.values(STORAGE).forEach(key=>localStorage.removeItem(key));migrateData();applySettings();showToast("Dados locais apagados");renderView("dados")}
async function runSelfTest(){const el=document.getElementById("selfTestResult");if(!el)return;el.innerHTML="<small>Testando…</small>";const tests=[];tests.push(["Service Worker suportado","serviceWorker" in navigator]);let reg=false;try{if("serviceWorker" in navigator){await navigator.serviceWorker.ready;reg=true}}catch{}tests.push(["Service Worker registrado",reg]);let cacheOk=false;try{cacheOk=!!(await caches.match(new URL("./app.js",location.href).href))&&!!(await caches.match(new URL("./styles.css",location.href).href))&&!!(await caches.match(new URL("./icone-192.png",location.href).href))}catch{}tests.push(["Arquivos essenciais no cache",cacheOk]);let storageOk=false;try{localStorage.setItem("__survival_test","1");storageOk=localStorage.getItem("__survival_test")==="1";localStorage.removeItem("__survival_test")}catch{}tests.push(["Armazenamento local",storageOk]);tests.push(["PWA em modo instalado",window.matchMedia?.("(display-mode: standalone)").matches||!!navigator.standalone]);const essential=tests.slice(0,4).every(x=>x[1]);el.innerHTML=`<div class="test-list">${tests.map(([n,ok],idx)=>`<div class="test-row"><span>${n}</span><strong class="${ok?"test-ok":idx===4?"":"test-bad"}">${ok?"✓":idx===4?"não instalado":"✕"}</strong></div>`).join("")}</div><div class="notice ${essential?"":"danger"}"><strong>${essential?"PRONTO PARA OFFLINE ✓":"REVISE ANTES DE DEPENDER DO OFFLINE"}</strong></div>`}
function searchDatabase(){const em=EMERGENCIES.map(i=>({type:"emergency",id:i.id,icon:i.icon,title:i.title,description:i.summary,keywords:normalizeText(`${i.title} ${i.summary} ${i.steps.join(" ")} ${i.dont?.join(" ")||""} ${SEARCH_ALIASES[i.id]||""}`)}));const mods=MODULES.map(i=>({type:"view",id:i[0],icon:i[1],title:i[2],description:i[3],keywords:normalizeText(`${i[2]} ${i[3]}`)}));return [...em,...mods]}
function searchEmergencies(q){const text=normalizeText(q);if(!text)return EMERGENCIES;return EMERGENCIES.filter(i=>normalizeText(`${i.title} ${i.summary} ${i.steps.join(" ")} ${SEARCH_ALIASES[i.id]||""}`).includes(text))}

view.addEventListener("click",event=>{
  const fav=event.target.closest("[data-fav-type]");if(fav){event.stopPropagation();toggleFavorite(fav.dataset.favType,fav.dataset.favId);if(modal.hidden)renderView(currentView());else showEmergency(fav.dataset.favId);return}
  const fo=event.target.closest("[data-favorite-open]");if(fo){fo.dataset.favoriteOpen==="emergency"?showEmergency(fo.dataset.favoriteId):renderView(fo.dataset.favoriteId);return}
  const nav=event.target.closest("[data-nav]");if(nav){renderView(nav.dataset.nav);return}
  const emergency=event.target.closest("[data-emergency]");if(emergency){showEmergency(emergency.dataset.emergency);return}
  const gps=event.target.closest("[data-gps]");if(gps){getGPS(gps.dataset.gps);return}
  const copy=event.target.closest("[data-copy]");if(copy){copyText(copy.dataset.copy);return}
  const delta=event.target.closest("[data-inventory-delta]");if(delta){const items=getInventory(),i=items.find(x=>x.id===delta.dataset.id);if(i){i.quantity=Math.max(0,Number(i.quantity)+Number(delta.dataset.inventoryDelta));saveJSON(STORAGE.inventory,items);renderInventory()}return}
  const pairs=[["[data-edit-check]",editChecklist,"editCheck"],["[data-edit-contact]",editContact,"editContact"],["[data-edit-inventory]",editInventory,"editInventory"],["[data-edit-maintenance]",editMaintenance,"editMaintenance"],["[data-edit-resource]",editResource,"editResource"]];for(const [sel,fn,key] of pairs){const b=event.target.closest(sel);if(b){fn(b.dataset[key]);return}}
  const deletes=[["[data-delete-check]",STORAGE.checklist,getChecklist,renderChecklist,"deleteCheck"],["[data-delete-contact]",STORAGE.contacts,getContacts,renderContacts,"deleteContact"],["[data-delete-journal]",STORAGE.journal,getJournal,renderJournal,"deleteJournal"],["[data-delete-inventory]",STORAGE.inventory,getInventory,renderInventory,"deleteInventory"],["[data-delete-maintenance]",STORAGE.maintenance,getMaintenance,renderMaintenance,"deleteMaintenance"],["[data-delete-resource]",STORAGE.resources,getResources,renderResources,"deleteResource"]];for(const [sel,key,getter,renderer,dataKey] of deletes){const b=event.target.closest(sel);if(b){if(confirm("Excluir este registro?")){saveJSON(key,getter().filter(x=>x.id!==b.dataset[dataKey]));renderer()}return}}
  const action=event.target.closest("[data-action]");if(action){switch(action.dataset.action){case"export":exportBackup();break;case"import":importInput.click();break;case"clear":clearData();break;case"self-test":runSelfTest();break;case"toggle-text":{const s=getSettings();s.textLarge=!s.textLarge;saveJSON(STORAGE.settings,s);applySettings();renderMore();break}case"start-compass":startCompass();break;case"stop-compass":stopCompass();const n=document.getElementById("compassNote");if(n)n.textContent="Sensor parado.";break}}
});
view.addEventListener("input",e=>{if(e.target.id==="emergencySearch"){const box=document.getElementById("emergencyList");if(box)box.innerHTML=renderEmergencyList(searchEmergencies(e.target.value))}});
view.addEventListener("change",e=>{const c=e.target.closest("[data-check]");if(!c)return;const items=getChecklist(),i=items.find(x=>x.id===c.dataset.check);if(i){i.done=c.checked;saveJSON(STORAGE.checklist,items);renderChecklist()}});
view.addEventListener("submit",e=>{e.preventDefault();const f=e.target,d=new FormData(f);
  if(f.id==="checklistAddForm"){const a=getChecklist();a.push({id:uid("check"),text:String(d.get("text")).trim(),category:String(d.get("category")||"").trim(),done:false});saveJSON(STORAGE.checklist,a);renderChecklist();return}
  if(f.id==="contactAddForm"){const a=getContacts();a.push({id:uid("contact"),name:String(d.get("name")).trim(),phone:String(d.get("phone")).trim(),note:String(d.get("note")||"").trim()});saveJSON(STORAGE.contacts,a);renderContacts();return}
  if(f.id==="planForm"){saveJSON(STORAGE.plan,{meeting:String(d.get("meeting")||"").trim(),backupMeeting:String(d.get("backupMeeting")||"").trim(),radio:String(d.get("radio")||"").trim(),checkin:String(d.get("checkin")||"").trim(),backupMethod:String(d.get("backupMethod")||"").trim(),message:String(d.get("message")||"").trim(),notes:String(d.get("notes")||"").trim()});showToast("Plano salvo");return}
  if(f.id==="iceForm"){saveJSON(STORAGE.ice,Object.fromEntries([...d.entries()].map(([k,v])=>[k,String(v).trim()])));showToast("Ficha ICE salva");return}
  if(f.id==="journalForm"){const a=getJournal(),p=d.get("withLocation")?getLastPosition():null;a.push({id:uid("journal"),timestamp:new Date().toISOString(),type:String(d.get("type")),text:String(d.get("text")).trim(),position:p?{lat:p.lat,lon:p.lon}:null});saveJSON(STORAGE.journal,a);renderJournal();return}
  if(f.id==="inventoryForm"){const a=getInventory();a.push({id:uid("stock"),name:String(d.get("name")).trim(),category:String(d.get("category")||"").trim(),quantity:Number(d.get("quantity")),unit:String(d.get("unit")||"").trim(),minimum:Number(d.get("minimum")||0),expiry:String(d.get("expiry")||"")});saveJSON(STORAGE.inventory,a);renderInventory();return}
  if(f.id==="maintenanceForm"){const a=getMaintenance();a.push({id:uid("maint"),name:String(d.get("name")).trim(),due:String(d.get("due")),note:String(d.get("note")||"").trim()});saveJSON(STORAGE.maintenance,a);renderMaintenance();return}
  if(f.id==="resourceForm"){const a=getResources();a.push({id:uid("res"),type:String(d.get("type")),name:String(d.get("name")).trim(),reference:String(d.get("reference")||"").trim(),note:String(d.get("note")||"").trim()});saveJSON(STORAGE.resources,a);renderResources();return}
  if(f.id==="sosForm"){const text=`SOS | Pessoas: ${d.get("people")} | Feridos: ${d.get("injured")} | Situação: ${d.get("situation")} | Local: ${d.get("coords")||"não informado"} | Preciso: ${d.get("need")||"ajuda"} | Próximo contato: ${d.get("next")||"a definir"}`,r=document.getElementById("sosResult");r.hidden=false;r.innerHTML=`<div class="sos-output">${escapeHTML(text)}</div><button type="button" class="btn" data-copy="${escapeHTML(text)}">Copiar mensagem</button>`;return}
  const handlers={mainWaterForm:()=>calculateWater(f,"mainWaterResult"),calcPlanWaterForm:()=>calculateWater(f,"calcPlanWaterResult"),waterReserveForm:()=>calculateWaterReserve(f,"waterReserveResult"),calcReserveForm:()=>calculateWaterReserve(f,"calcReserveResult"),energyBudgetForm:()=>calculateBudget(f,"energyBudgetResult"),calcBudgetForm:()=>calculateBudget(f,"calcBudgetResult"),energyRuntimeForm:()=>calculateRuntime(f,"energyRuntimeResult"),calcEnergyRuntimeForm:()=>calculateRuntime(f,"calcEnergyRuntimeResult"),energyPowerForm:()=>calculatePower(f,"energyPowerResult"),calcEnergyPowerForm:()=>calculatePower(f,"calcEnergyPowerResult"),navDistanceForm:()=>calculateDistance(f,"nav"),calcNavDistanceForm:()=>calculateDistance(f,"calcNav"),navDmsForm:()=>calculateDMS(f,"nav"),calcNavDmsForm:()=>calculateDMS(f,"calcNav"),navDecimalForm:()=>calculateDecimal(f,"nav"),calcNavDecimalForm:()=>calculateDecimal(f,"calcNav"),whForm:()=>calculateWh(f),travelForm:()=>calculateTravel(f),ropeForm:()=>calculateRope(f),unitForm:()=>calculateUnit(f),heatForm:()=>calculateHeat(f),windChillForm:()=>calculateWindChill(f),daylightForm:()=>calculateDaylight(f)};if(handlers[f.id])handlers[f.id]();
});
modal.addEventListener("click",e=>{if(e.target.closest("[data-close-modal]"))closeModal();const fav=e.target.closest("[data-fav-type]");if(fav){toggleFavorite(fav.dataset.favType,fav.dataset.favId);showEmergency(fav.dataset.favId)}});
modal.addEventListener("submit",e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==="checklistEditForm"){const a=getChecklist(),i=a.find(x=>x.id===f.dataset.id);if(i){i.text=String(d.get("text")).trim();i.category=String(d.get("category")||"").trim();saveJSON(STORAGE.checklist,a)}closeModal();renderChecklist()}if(f.id==="contactEditForm"){const a=getContacts(),i=a.find(x=>x.id===f.dataset.id);if(i){i.name=String(d.get("name")).trim();i.phone=String(d.get("phone")).trim();i.note=String(d.get("note")||"").trim();saveJSON(STORAGE.contacts,a)}closeModal();renderContacts()}if(f.id==="inventoryEditForm"){const a=getInventory(),i=a.find(x=>x.id===f.dataset.id);if(i){i.name=String(d.get("name")).trim();i.quantity=Number(d.get("quantity"));i.unit=String(d.get("unit")||"").trim();i.minimum=Number(d.get("minimum")||0);i.expiry=String(d.get("expiry")||"");i.category=String(d.get("category")||"").trim();saveJSON(STORAGE.inventory,a)}closeModal();renderInventory()}if(f.id==="maintenanceEditForm"){const a=getMaintenance(),i=a.find(x=>x.id===f.dataset.id);if(i){i.name=String(d.get("name")).trim();i.due=String(d.get("due"));i.note=String(d.get("note")||"").trim();saveJSON(STORAGE.maintenance,a)}closeModal();renderMaintenance()}if(f.id==="resourceEditForm"){const a=getResources(),i=a.find(x=>x.id===f.dataset.id);if(i){i.type=String(d.get("type")).trim();i.name=String(d.get("name")).trim();i.reference=String(d.get("reference")||"").trim();i.note=String(d.get("note")||"").trim();saveJSON(STORAGE.resources,a)}closeModal();renderResources()}});

document.querySelector(".bottom-nav").addEventListener("click",e=>{const b=e.target.closest("[data-nav]");if(b)renderView(b.dataset.nav)});
document.getElementById("homeButton").addEventListener("click",()=>renderView("home"));
importInput.addEventListener("change",()=>{const f=importInput.files?.[0];if(f)importBackup(f)});
function currentView(){return currentViewName||"home"}
function updateConnection(){if(navigator.onLine){networkStatus.textContent=offlineReady?"● online · cache offline pronto":"● online · preparando offline";networkStatus.className="online"}else{networkStatus.textContent=offlineReady?"● offline · pronto":"● offline";networkStatus.className="offline"}}
window.addEventListener("online",updateConnection);window.addEventListener("offline",updateConnection);window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();installPrompt=e;installButton.hidden=false});installButton.addEventListener("click",async()=>{if(!installPrompt){showToast("Use o menu do navegador para instalar");return}installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;installButton.hidden=true});window.addEventListener("appinstalled",()=>{installPrompt=null;installButton.hidden=true;showToast("Aplicativo instalado")});
async function registerServiceWorker(){if(!("serviceWorker" in navigator))return;try{await navigator.serviceWorker.register("./service-worker.js",{scope:"./"});await navigator.serviceWorker.ready;offlineReady=true;updateConnection()}catch(e){console.error(e)}}
function initialView(){const v=new URLSearchParams(location.search).get("view");return v||"home"}
migrateData();applySettings();updateConnection();renderView(initialView());registerServiceWorker();
